## Counting Words, Sentences, Paragraphs

### Word Counter

```xiom
fn count_words(text: Str) -> Int {
  if text.len() == 0 { return 0; };
  let mut count = 0;
  let mut in_word = false;
  let mut i = 0;
  while i < text.len() {
    let c = text.get(i).unwrap();
    let is_space = c == ' ' || c == '\n' || c == '\t';

    if is_space {
      in_word = false;
    } else if !in_word {
      count += 1;
      in_word = true;
    };
    i += 1;
  };
  count
}
```

### Sentence Counter

```xiom
fn count_sentences(text: Str) -> Int {
  let mut count = 0;
  let mut i = 0;
  while i < text.len() {
    let c = text.get(i).unwrap();
    if c == '.' || c == '!' || c == '?' {
      count += 1;
    };
    i += 1;
  };
  count
}
```

### Paragraph Counter

```xiom
fn count_paragraphs(text: Str) -> Int {
