use xiom.io;
fn count_words(text: Str) -> Int {
  if text.len() == 0 { return 0; };
  var count = 0;
  var in_word = false;
  var i = 0;
  while i < text.len() {
    let c = text.char_at(i);
    if c == ' ' {
      in_word = false;
    } else if !in_word {
      count += 1;
      in_word = true;
    };
    i += 1;
  };
  count
}

fn count_sentences(text: Str) -> Int {
  var count = 0;
  var i = 0;
  while i < text.len() {
    let c = text.char_at(i);
    if c == '.' || c == '!' || c == '?' { count += 1; };
    i += 1;
  };
  count
}

fn main() -> Int {
  let text = "Hello world. This is a test! How are you?";
  io.println(count_words(text).to_str());
  io.println(count_sentences(text).to_str());
  return 0;
}
